async def act(page):
    """
    Navigate to the Sales Orders grid and count orders with status 'complete' for each
    month May..December 2022. Returns a newline-separated string with lines in MM:COUNT format.
    """
    import re
    import calendar
    from datetime import date
    import asyncio

    # 1) Navigate to Sales > Orders grid (deterministic starting URL)
    await page.goto('/index.php/admin/sales_order/')
    await page.wait_for_load_state('networkidle')
    await asyncio.sleep(0.3)

    # Helper: find a textbox by inspecting accessible-name first, then attributes
    async def find_date_textbox(hints):
        for h in hints:
            try:
                loc = page.get_by_role('textbox', name=re.compile(h, re.I))
                if await loc.count() > 0:
                    return loc.nth(0)
            except Exception:
                pass
        # Fallback: scan all textboxes and inspect attributes
        all_tbs = page.get_by_role('textbox')
        try:
            total = await all_tbs.count()
        except Exception:
            total = 0
        for i in range(total):
            tb = all_tbs.nth(i)
            try:
                parts = []
                for a in ('name', 'aria-label', 'placeholder', 'title', 'id'):
                    v = await tb.get_attribute(a)
                    if v:
                        parts.append(v)
                hay = ' '.join(parts).lower()
                for h in hints:
                    if h.lower() in hay:
                        return tb
            except Exception:
                continue
        return None

    # Typical Magento filter input names/hints
    from_input = await find_date_textbox(['from', 'created from', 'created_from', 'created_at[from]'])
    to_input = await find_date_textbox(['to', 'created to', 'created_to', 'created_at[to]'])

    # If not found, attempt a simple fallback: first two textboxes on the page
    if not from_input or not to_input:
        all_tbs = page.get_by_role('textbox')
        try:
            if await all_tbs.count() >= 2:
                if not from_input:
                    from_input = all_tbs.nth(0)
                if not to_input:
                    to_input = all_tbs.nth(1)
        except Exception:
            pass

    if not from_input or not to_input:
        raise RuntimeError('Could not locate from/to date textboxes on the Sales Orders grid.')

    # Locate a Search/Filter button. Prefer clearly named button, otherwise scan buttons.
    search_button = None
    try:
        cand = page.get_by_role('button', name=re.compile(r'(Search|Filter|Apply|Go)', re.I))
        if await cand.count() > 0:
            search_button = cand.nth(0)
    except Exception:
        search_button = None

    if not search_button:
        buttons = page.get_by_role('button')
        try:
            btn_count = await buttons.count()
        except Exception:
            btn_count = 0
        for i in range(btn_count):
            b = buttons.nth(i)
            try:
                title = (await b.get_attribute('title')) or ''
                aria = (await b.get_attribute('aria-label')) or ''
                texts = await b.all_inner_texts()
                txt = ' '.join(texts)
                hay = ' '.join([title, aria, txt]).lower()
                if re.search(r'\b(search|filter|apply|go)\b', hay, re.I):
                    search_button = b
                    break
            except Exception:
                continue

    if not search_button:
        raise RuntimeError('Could not locate Search/Filter button on the Orders grid.')

    # Helper: count rows containing 'complete' across all pagination pages
    async def count_complete_across_pages():
        async def count_on_page():
            try:
                table = page.get_by_role('table').nth(0)
            except Exception:
                return 0
            try:
                rows = table.get_by_role('row')
                rcount = await rows.count()
            except Exception:
                return 0
            cnt = 0
            for ri in range(rcount):
                row = rows.nth(ri)
                try:
                    # skip header rows containing columnheader
                    if await row.get_by_role('columnheader').count() > 0:
                        continue
                except Exception:
                    pass
                try:
                    cells = row.get_by_role('cell')
                    if await cells.count() == 0:
                        continue
                    cell_texts = await cells.all_inner_texts()
                except Exception:
                    cell_texts = []
                if any('complete' in (t or '').lower() for t in cell_texts):
                    cnt += 1
            return cnt

        total = await count_on_page()
        # Paginate via Next link/button, capped iterations
        for _ in range(200):
            next_ctrl = None
            try:
                nl = page.get_by_role('link', name=re.compile(r'next', re.I))
                if await nl.count() > 0:
                    next_ctrl = nl.nth(0)
            except Exception:
                next_ctrl = None
            if not next_ctrl:
                try:
                    nb = page.get_by_role('button', name=re.compile(r'next', re.I))
                    if await nb.count() > 0:
                        next_ctrl = nb.nth(0)
                except Exception:
                    next_ctrl = None
            if not next_ctrl:
                break
            try:
                aria_disabled = await next_ctrl.get_attribute('aria-disabled')
                cls = await next_ctrl.get_attribute('class')
                if (aria_disabled and aria_disabled.lower() in ('true', '1')) or (cls and 'disabled' in (cls or '').lower()):
                    break
            except Exception:
                pass
            try:
                await next_ctrl.click()
                await page.wait_for_load_state('networkidle')
                await asyncio.sleep(0.4)
            except Exception:
                break
            total += await count_on_page()
        return total

    results = []
    for month in range(5, 13):  # May..Dec
        year = 2022
        start = date(year, month, 1)
        end = date(year, month, calendar.monthrange(year, month)[1])
        start_iso = start.strftime('%Y-%m-%d')
        end_iso = end.strftime('%Y-%m-%d')

        # Fill date inputs and apply filter
        await from_input.fill('')
        await to_input.fill('')
        await from_input.fill(start_iso)
        await to_input.fill(end_iso)
        await search_button.click()
        await page.wait_for_load_state('networkidle')
        await asyncio.sleep(0.6)

        cnt = await count_complete_across_pages()
        results.append(f"{month:02d}:{cnt}")

    out = "\n".join(results)
    print(out)
    return out

